async function parseAndImportLegacySQL(sqlPath, targetDbPath) {
  migrationStatus.message = "Parsing and Importing SQL Data (legacy format)...";
  const db2 = await (0, import_sqlite6.open)({ filename: targetDbPath, driver: import_sqlite35.default.Database });
  try {
    await db2.run("PRAGMA busy_timeout = 30000");
    await ensureStagingFts(db2);
    await ensureMigrationErrorsTable(db2);
    const fileStream = import_fs28.default.createReadStream(sqlPath);
    const rl = import_readline.default.createInterface({
      input: fileStream,
      crlfDelay: Infinity
    });
    let linesProcessed2 = 0;
    let linesMigrated = 0;
    for await (const line of rl) {
      const trimmedLine = line.trim();
      if (linesProcessed2 % 500 === 0) {
        await new Promise((resolve) => setImmediate(resolve));
      }
      if (!trimmedLine) {
        linesProcessed2++;
        if (linesProcessed2 % 1e3 === 0) {
          migrationStatus.progress = Math.min(99, Math.floor(linesProcessed2 / 1e3));
          migrationStatus.message = `Processed ${linesProcessed2} lines, migrated ${linesMigrated} rows...`;
        }
        continue;
      }
      let migrated = false;
      try {
        if (trimmedLine.toUpperCase().startsWith("INSERT INTO LEGACY_RETURNS")) {
          migrated = await processReturnsLine(trimmedLine, db2);
        } else if (trimmedLine.toUpperCase().startsWith("INSERT INTO LEGACY_STOCK") || trimmedLine.toUpperCase().startsWith("INSERT INTO LEGACY_BATCHES")) {
          migrated = await processInventoryLine(trimmedLine, db2);
        } else if (trimmedLine.toUpperCase().startsWith("INSERT INTO LEGACY_SALES") || trimmedLine.toUpperCase().startsWith("INSERT INTO LEGACY_SALEITEMS") || trimmedLine.toUpperCase().startsWith("INSERT INTO LEGACY_SALE_ITEMS")) {
          migrated = await processSalesLine(trimmedLine, db2);
        }
      } catch (err) {
        migrationStatus.errorCount++;
        const errMsg = err.message || "Unknown processing error";
        await db2.run(
          "INSERT INTO migration_errors (file_name, row_index, raw_data, error_message) VALUES (?, ?, ?, ?)",
          [import_path31.default.basename(sqlPath), linesProcessed2, trimmedLine.slice(0, 1e3), errMsg]
        );
      }
      if (migrated) {
        linesMigrated++;
      }
      linesProcessed2++;
      if (linesProcessed2 % 1e3 === 0) {
        migrationStatus.progress = Math.min(99, Math.floor(linesProcessed2 / 1e3));
        migrationStatus.message = `Processed ${linesProcessed2} lines, migrated ${linesMigrated} rows...`;
      }
    }
    migrationStatus.message = `Migration Complete! Processed ${linesProcessed2} lines, migrated ${linesMigrated} rows`;
  } finally {
    await db2.close();
  }
}
