async function tableExists2(db2, name) {
  const row = await db2.get("SELECT name FROM sqlite_master WHERE type='table' AND name = ?", [name]);
  return !!row;
}
async function columnExists(db2, table, column) {
  const cols = await db2.all(`PRAGMA table_info(${table})`);
  return cols.some((c) => String(c.name).toLowerCase() === column.toLowerCase());
}
